sys_variable_value.value:
(function execute(inputs, outputs) {
    var ports_collection = [];
    var ports = new GlideRecord('x_snc_duty_travel_ports');
    ports.addEncodedQuery('portISNOTEMPTY');
    ports.setLimit(inputs.limit);
    ports.query();
    while(ports.next()) {
        ports_collection.push({
            port: ports.getDisplayValue('port')
        });
    }
    outputs.ports_json = JSON.stringify(ports_collection);
})(inputs, outputs);

